        "貨幣市場基金指運用於銀行存款、短期票券及附買回交易之總金額達基金淨資產價值百分之七十五以上者",
        "貨幣市場基金之加權平均存續期間不得大於一百八十日，運用標的為附買回交易者，應以附買回交易之期間計算"
