      "number": 1,
      "stem": "甲公司存貨採用定期盤存制，X8 年底報導之總資產為$3,200,000及當年度淨利為$170,000。甲公司於 X9 年發現X7 年底有一批買入價格為$46,000起運點交貨之商品，在X7 年底計入進貨，但因該商品於X8 年1 月5 日方送抵甲公司，因此未將該商品計入X7 年底之期末存貨金額。另外，甲公司於X8 年底以售價$30,000賣出成本為$20,000之存貨，出售條件為目的地交貨，且控制於目的地才移轉，該批商品於X9 年1 月2 日送達買方公司；甲公司將此存貨相關之銷貨收入認列為X9 年度銷貨，且未將此批存貨計入X8 年底之期末存貨。試問甲公司X8 年度正確之資產總額及淨利金額分別為何？",
