      "sourceId": "accounting-05",
      "number": 5,
      "stem": "Z 公司於編製 X0 年 12 月 31 日財務報表時，有下列三筆不同情況之債務：甲.將於 X5 年 12 月 31 日到期之負債，但債權人可隨時要求償還。乙.將於X2 年12 月1 日到期之長期銀行借款負債，在X0 年11月10 日Z 公司違反了債務合約條款，銀行得隨時請求Z 公司返還該借款。X0 年12 月20 日Z 公司改善其違約情況並與銀行達成協議，銀行同意不行使此次 Z 公司違反合約條款之還款請求權。丙.將於X1 年2 月16 日到期之負債。債權人同意將到期日延長至X3 年2 月16 日，該合約於X1 年 1 月 10 日重新簽訂。假設Z公司之財務報表將於X1年3月1日發布，試問Z公司X0年12月31日資產負債表中應報導為流動負債之負債共有幾筆？",
