      "stem": "甲公司於X3 年 1 月 1 日購買價值$12,000,000的油井設備。該設備使用年限為10 年，無殘值，採直線法折舊，10 年後拆除該設備的預計成本為$2,400,000(以利率10%計算之複利現值為 $925,304)。根據該公司情況10%利率應屬合理。試問甲公司X3 年度有關該交易事項應認列之相關費用及金額為何？",
