      "subject": "accounting",
      "sourceId": "accounting-02",
      "number": 10,
      "stem": "甲公司於 X2 年 1 月 1 日與乙公司簽訂銷售商品之合約，每件商品售價$300，成本$200。但若乙公司於 X2 年全年購買超過 4,000 件商品，則合約明定每件商品售價將減少為$250 (並追溯至當年度已售出之前 4,000 件)。甲公司於 X2 年第一季，銷售 500 件商品予乙公司。甲公司估計，乙公司於 X2 年不會購買超過 4,000 件商品。乙公司於 X2 年 5 月擴大營運規模，甲公司於 X2 年第二季銷售額外 2,000 件商品予乙公司。基於此新情況，甲公司估計乙公司將會於 X2 年購買超過 4,000 件商品。試問甲公司第二季應認列的銷貨收入金額為何？",
