      "year": 109,
      "session": 1,
      "subject": "accounting",
      "sourceId": "accounting-08",
      "number": 11,
      "stem": "甲公司於 X3 年初以固定價格$1,000,000 承包一項建造合約，該合約之履約義務係隨時間逐步履約者，並預定以 3 年期間完成工程。X3、X4 年相關資料如下： X3 年 X4 年本期發生已完成工作之合約成本 $200,000 $400,000 估計總合約成本 $800,000 $800,000 至今完成程度？ ？當年度工程進度請款金額 $300,000 $500,000 實際收款金額 $240,000 $400,000 甲公司以累計完工已發生之合約成本，占估計總合約成本之比例衡量建造合約完成程度。試問甲公司於 X4 年底資產負債表中應列報該建造合約之合約資產或合約負債之金額為何？",
