      "session": 2,
      "subject": "law",
      "sourceId": "law-01",
      "number": 26,
      "stem": "關於證券交易法對於公開發行公司財務報告之相關規範，下列何者正確？Ⅰ.公開發行公司須於每會計年度終了後六個月內，公告並申報會計師查核簽證、董事會通過及監察人承認之年度財務報告；Ⅱ.公開發行公司須於每會計年度第一季、第二季及第三季終了後三十日內，公告並申報經會計師核閱及提報董事會之財務報告；Ⅲ.上市公司依法須公告、申報之財務報告事項，尚須將抄本送證券交易所；Ⅳ.公開發行公司在重整期間，仍須依法揭露財務報告",
