      "stem": "目前有兩股票：股票A 的期望報酬率與報酬率標準差分別是 5%和 30%，以及股票 B 的期望報酬率與報酬率標準差分別是 10%和 20%。若兩股票報酬率相關係數是-1，現在利用該兩種股票組成一個報酬率標準差最小的投資組合，試問該投資組合之期望報酬為多少？",
