      "subject": "investment",
      "sourceId": "investment-03",
      "number": 20,
      "stem": "某投資人透過目前所持有上市股票組合與定期存款兩資產做適當配置，該上市股票組合的期望報酬率與報酬率標準差分別是 12% 和 25%，以及銀行定期存款為固定利率 2%。若該投資者最多只能忍受 18% 的虧損，虧損大於風險承受度的機率為 5%。在報酬為常態分配的假設下，該投資人約應投資多少比例在定期存款（\\(Z_{0.95}=1.65\\)、\\(Z_{0.975}=1.96\\)）？",
