      "stem": "某上市公司發行一個每張面額十萬元的兩年期債券，票面利率 10%，每年付息一次，發行當時的債券殖利率為 8%。一年後(距到期日尚有 1 年)，市場對此同等級債券所要求的殖利率下降至7%。試計算出因時間流逝對該債券價格的影響金額約為多少(即債券回歸面額效果)？",
