      "number": 24,
      "stem": "某上市公司去年發行了一檔兩年期公司債，票面利率為2.5%，每年付息一次。該債券剛支付過第一年的債息(距離到期還剩下一年)，目前市場價格為$100.46。若市場上一年期零息政府公債殖利率等於 1%，請問在違約回收率為 20%的假設下，該上市公司在一年內違約的機率應該最接近多少？(假設債券面額均為$100)：",
