      "subject": "investment",
      "sourceId": "investment-10",
      "number": 25,
      "stem": "投資人以債券保證金交易方式向券商買進債券，試問下列敘述何者正確？ I、就證券商而言，是一種賣斷交易與附賣回交易的組合 II、在保證金交易的承作期間內，標的債券仍然是由券商保有 III、在保證金交易的承作期間內，債券之債息收入是屬於券商 IV、投資人須繳交保證金給證券櫃檯買賣中心：",
